    const right = el('div', 'stack'); const health = el('div', 'card-body');
    append(health, kv(t('Usimamizi', 'Moderation'), badge(enabled ? t('Unafanya kazi', 'Active') : t('Umesitishwa', 'Paused'), enabled ? '' : 'warn', enabled ? 'check' : 'pause'), 'shield'), kv(t('Lugha ya group', 'Group language'), data.language === 'en' ? 'English' : 'Kiswahili', 'globe'), kv(t('Makosa ya links / forwards', 'Link / forward strikes'), '24h → 7d → ∞', 'incidents'), kv(t('Whitelist ya ziada', 'Additional allowlist'), String(data.rules.length), 'link'), kv(t('Spam ya commands', 'Command spam'), data.settings.command_spam_enabled !== false ? t('Futa tu · imewashwa', 'Delete only · on') : t('Imezimwa', 'Off'), 'code'), kv(t('Ulinzi wa flood', 'Flood control'), data.settings.flood_enabled ? t('Umewashwa', 'On') : t('Umezimwa', 'Off'), 'activity'), kv(t('Ukaguzi wa wanaojiunga', 'Join screening'), data.settings.join_gate_enabled ? t('Umewashwa', 'On') : t('Umezimwa', 'Off'), 'joins'));
    right.append(card(t('Hali ya group', 'Group status'), [health], '', 'shield'));
