    const form = el('form'); const message = field(t('Ujumbe kwa admins wa group', 'Message to the group admins'), { name: 'appealMessage', rows: 5, maxLength: 1000, note: t('Rufaa moja kwa tukio. Hadi herufi 1,000. Usitume nywila au token.', 'One appeal per case. Up to 1,000 characters. Do not include passwords or tokens.') }); message.input.required = true; message.input.minLength = 5; const actions = el('div', 'modal-actions'); const send = button(t('Tuma rufaa', 'Submit appeal'), null, '', 'send'); send.type = 'submit'; append(actions, button(t('Ghairi', 'Cancel'), () => modal.close(), 'secondary', 'close'), send); append(form, el('p', 'modal-copy', t('Admins wa group hili wataona ujumbe wako na tukio husika. Rufaa haibadilishi ban moja kwa moja.', 'The group’s admins will see your message and the related incident. Submitting an appeal does not automatically change the ban.')), message.box, actions); form.addEventListener('submit', event => { event.preventDefault(); if (!form.reportValidity()) return; modal.close(); perform('appeal_create', { incidentId: row.id, message: message.input.value.trim() }, { chatId: String(row.chat_id), success: t('Rufaa imetumwa kwa ukaguzi.', 'Your appeal is ready for review.') }); }); append(modal, heading, form); modal.showModal();
